--- trial4/src/scope.c
+++ trial5/src/scope.c
@@ -18,12 +18,23 @@
 	uint64_t hash = (uintptr_t)context;
 	hash = (hash ^ (uintptr_t)parent) * UINT64_C(1099511628211);
 	hash = (hash ^ (uintptr_t)indices) * UINT64_C(1099511628211);
-	hash = (hash ^ (uintptr_t)type) * UINT64_C(1099511628211);
+	if (type) {
+		hash = (hash ^ (uintptr_t)type->core) * UINT64_C(1099511628211);
+		hash = (hash ^ (uintptr_t)type->classifier) * UINT64_C(1099511628211);
+	}
 	if (!typing->scopes.capacity && pg_index_init(&typing->scopes)) return NULL;
 	for (struct pg_index_entry *p = pg_index_candidates(&typing->scopes, hash); p; p = p->next) {
 		const struct pg_scope *scope = (const void *)p;
 		if (p->hash != hash || scope->context != context || scope->parent != parent) continue;
-		if (scope->indices == indices && scope->type == type) return scope;
+		if (scope->indices != indices) continue;
+		if (scope->type != type && (!scope->type || !type ||
+			scope->type->core != type->core || scope->type->classifier != type->classifier)) continue;
+		/* A declaration retains its checked typed fact, not alternative
+		 * formation history. Raw transport stays unaccepted; only a canonical
+		 * admitted input can replace its descriptive type before admission. */
+		if (!scope->admission_owner && type && type->admission_owner == typing->owner_key &&
+			pg_occurrence_owned_by(type, typing)) ((struct pg_scope *)scope)->type = type;
+		return scope;
 	}
 	struct pg_scope *scope = pg_alloc(typing->graph, sizeof(*scope));
 	if (!scope) return NULL;
